import assert from "node:assert/strict";
import { test } from "node:test";
import { defaultRoute, describeCapability, preferredSearchProvider } from "../index.js";

/** Minimal fake of the web seam shape dsh 0.2.1-rc.4 exposes. */
function fakeWeb({ searchProviders, fetchProviders, config, env } = {}) {
	return {
		searchProviders: searchProviders ?? new Map(),
		fetchProviders: fetchProviders ?? new Map(),
		config: config ?? {},
		searchProviderEnv: env?.search ?? "",
		fetchProviderEnv: env?.fetch ?? "",
	};
}

function provider(id, available) {
	return {
		id,
		available: () => available,
	};
}

test("single available provider resolves as ready", () => {
	const web = fakeWeb({
		searchProviders: new Map([["deepseek-official", provider("deepseek-official", true)]]),
	});
	assert.equal(describeCapability(web, "search"), "ready (deepseek-official)");
});

test("no provider registered", () => {
	assert.equal(describeCapability(fakeWeb(), "fetch"), "no provider registered");
});

test("registered but unavailable is reported per provider", () => {
	const web = fakeWeb({
		fetchProviders: new Map([["http", provider("http", false)]]),
	});
	assert.equal(describeCapability(web, "fetch"), "registered but unavailable: http(unavailable)");
});

test("two usable providers without configuration are ambiguous", () => {
	const web = fakeWeb({
		searchProviders: new Map([
			["a", provider("a", true)],
			["b", provider("b", true)],
			["c", provider("c", false)],
		]),
	});
	assert.equal(describeCapability(web, "search"), "ambiguous: a,b");
});

test("configured id wins over env and unregistered peers", () => {
	const web = fakeWeb({
		fetchProviders: new Map([["http", provider("http", true)]]),
		config: { fetchProvider: { get: () => "http" } },
		env: { fetch: "other" },
	});
	assert.equal(describeCapability(web, "fetch"), "ready (http)");
});

test("configured id missing from the registry is explicit", () => {
	const web = fakeWeb({
		fetchProviders: new Map([["http", provider("http", true)]]),
		config: { fetchProvider: { get: () => "gone" } },
	});
	assert.equal(describeCapability(web, "fetch"), 'configured "gone" not registered');
});

test("configured but unavailable provider reports unavailable", () => {
	const web = fakeWeb({
		searchProviders: new Map([["deepseek-official", provider("deepseek-official", false)]]),
		config: { searchProvider: { get: () => "deepseek-official" } },
	});
	assert.equal(describeCapability(web, "search"), 'configured "deepseek-official" unavailable');
});

test("env DSH_WEB_*_PROVIDER is the configured fallback", () => {
	const web = fakeWeb({
		fetchProviders: new Map([["http", provider("http", true)]]),
		env: { fetch: "http" },
	});
	assert.equal(describeCapability(web, "fetch"), "ready (http)");
});

test("a throwing available() counts as unavailable", () => {
	const broken = {
		id: "broken",
		available: () => {
			throw new Error("no key");
		},
	};
	const web = fakeWeb({ fetchProviders: new Map([["broken", broken]]) });
	assert.equal(describeCapability(web, "fetch"), "registered but unavailable: broken(unavailable)");
});

test("an unexpected seam shape is named, not thrown", () => {
	const web = { searchProviders: [], fetchProviders: null };
	assert.equal(describeCapability(web, "search"), "unknown (unexpected seam shape)");
});

test("config slice read errors fall through to env", () => {
	const web = fakeWeb({
		fetchProviders: new Map([["http", provider("http", true)]]),
		config: { fetchProvider: { get: () => { throw new Error("volatile"); } } },
		env: { fetch: "http" },
	});
	assert.equal(describeCapability(web, "fetch"), "ready (http)");
});

/** The two search providers a 0.2.2-rc.5 composition registers. */
function rc5SearchProviders() {
	return new Map([
		["deepseek-official", provider("deepseek-official", true)],
		["deepseek-search-api", provider("deepseek-search-api", true)],
	]);
}

test("two usable providers resolve through the DeepSeek route preference", () => {
	const web = fakeWeb({ searchProviders: rc5SearchProviders() });
	assert.equal(
		describeCapability(web, "search", "deepseek-official"),
		"auto (deepseek-official for deepseek-official)",
	);
});

test("an account route also prefers the server-side search", () => {
	const web = fakeWeb({ searchProviders: rc5SearchProviders() });
	assert.equal(
		describeCapability(web, "search", "deepseek-account"),
		"auto (deepseek-official for deepseek-account)",
	);
});

test("a non-DeepSeek route prefers the Search API", () => {
	const web = fakeWeb({ searchProviders: rc5SearchProviders() });
	assert.equal(
		describeCapability(web, "search", "local"),
		"auto (deepseek-search-api for local)",
	);
});

test("an unknown route is named instead of guessed", () => {
	const web = fakeWeb({ searchProviders: rc5SearchProviders() });
	assert.equal(
		describeCapability(web, "search"),
		"auto (deepseek-search-api for an unknown route)",
	);
});

test("the preference does not hide a real ambiguity", () => {
	const web = fakeWeb({
		searchProviders: new Map([
			["a", provider("a", true)],
			["b", provider("b", true)],
		]),
	});
	assert.equal(describeCapability(web, "search", "deepseek-official"), "ambiguous: a,b");
});

test("fetch never applies the search preference", () => {
	const web = fakeWeb({
		fetchProviders: new Map([
			["http", provider("http", true)],
			["https", provider("https", true)],
		]),
	});
	assert.equal(describeCapability(web, "fetch", "deepseek-official"), "ambiguous: http,https");
});

test("preferredSearchProvider maps both DeepSeek routes", () => {
	assert.equal(preferredSearchProvider("deepseek-official"), "deepseek-official");
	assert.equal(preferredSearchProvider("deepseek-account"), "deepseek-official");
	assert.equal(preferredSearchProvider("pi-ai"), "deepseek-search-api");
	assert.equal(preferredSearchProvider(undefined), "deepseek-search-api");
});

test("defaultRoute reads the default model service", () => {
	const ctx = {
		get: (name) =>
			name === "agentDefaultModel"
				? { currentSelection: () => ({ provider: "deepseek-official", model: "deepseek-flash" }) }
				: undefined,
	};
	assert.equal(defaultRoute(ctx), "deepseek-official");
});

test("defaultRoute degrades to undefined when the service is absent or throws", () => {
	assert.equal(defaultRoute({ get: () => undefined }), undefined);
	assert.equal(
		defaultRoute({
			get: () => {
				throw new Error("service not ready");
			},
		}),
		undefined,
	);
	assert.equal(defaultRoute({ get: () => ({ currentSelection: () => ({ provider: "" }) }) }), undefined);
});
